  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Approves a pending application. Sends two information emails, one to the customer and one to the company.
   * Algorithm:
   *   1. If status is not PENDING, return false.
   *   2. If the related customer is not eligible for IPO (isEligibleForIPO() returns false), return false.
   *   3. Set status to APPROVAL.
   *   4. Create and send an information email to the customer.
   *   5. Create and send an information email to the company.
   *   6. Return true.
   * Related Features: status, customer, company, emails
   * Related Classes: Customer, Company, Email, ApplicationStatus
   * Input: None
   * Output: boolean - true if approval succeeds, false otherwise.
   * Pre-condition: Application status is PENDING and the related customer is eligible for IPO.
   * Post-condition: Status is APPROVAL. Two information emails are added to the emails list and sent.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean approve()
  {
    // 1. If status is not PENDING, return false.
    if (getStatus() != ApplicationStatus.PENDING) {
      return false;
    }
    // 2. If the related customer is not eligible for IPO (isEligibleForIPO() returns false), return false.
    Customer customer = getCustomer();
    if (customer == null || !customer.isEligibleForIPO()) {
      return false;
    }
    // 3. Set status to APPROVAL.
    setStatus(ApplicationStatus.APPROVAL);
    // 4. Create and send an information email to the customer.
    Email customerEmail = IpoFactory.eINSTANCE.createEmail();
    customerEmail.setReceiver(customer.getEmail());
    customerEmail.setContent("Your IPO application has been approved.");
    getEmails().add(customerEmail);
    // 5. Create and send an information email to the company.
    Email companyEmail = IpoFactory.eINSTANCE.createEmail();
    companyEmail.setReceiver(getCompany().getEmail());
    companyEmail.setContent("The IPO application for your company has been approved.");
    getEmails().add(companyEmail);
    // 6. Return true.
    return true;
  }

